def deep_merge_nodes(nodes):
    from collections import defaultdict

    def merge_into(target, source):
        for key, value in source.value:
            if key not in target.value:
                target.value.append((key, value))
            else:
                target_index = next(i for i, (k, _) in enumerate(target.value) if k == key)
                _, target_value = target.value[target_index]
                if isinstance(target_value, ruamel.yaml.nodes.MappingNode) and isinstance(value, ruamel.yaml.nodes.MappingNode):
                    merge_into(target_value, value)
                else:
                    target.value[target_index] = (key, value)

    merged_dict = defaultdict(lambda: None)
    for key, value in nodes:
        if merged_dict[key] is None:
            merged_dict[key] = value
        else:
            merge_into(merged_dict[key], value)

    return [(key, value) for key, value in merged_dict.items()]

