                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    graph_data = []
    for bin_ in hist.bins:
        if get_coordinate == "left":
            x = bin_.left_edge
        elif get_coordinate == "right":
            x = bin_.right_edge
        elif get_coordinate == "middle":
            x = (bin_.left_edge + bin_.right_edge) / 2
        else:
            raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

        y_values = make_value(bin_.content)
        if not isinstance(y_values, tuple):
            y_values = (y_values,)

        point_data = {field_names[i]: value for i, value in enumerate((x,) + y_values)}
        graph_data.append(point_data)

    graph = Graph(data=graph_data)
    if scale is True:
        graph.scale = hist.scale
    elif scale is not None:
        graph.scale = scale

    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not provide interface {iface}")

    for name in iface.names():
        if not hasattr(candidate, name):
            errors.append(f"Candidate does not define {name}")

    for name, attr in iface.namesAndDescriptions():
        if hasattr(attr, 'getSignatureString'):
            method = getattr(candidate, name, None)
            if method is None or not callable(method):
                errors.append(f"Candidate's {name} is not callable")
            else:
                expected_signature = attr.getSignatureString()
                try:
                    import inspect
                    actual_signature = inspect.signature(method)
                    if str(actual_signature) != expected_signature:
                        errors.append(f"Candidate's {name} has an incorrect signature: expected {expected_signature}, got {actual_signature}")
                except ImportError:
                    pass  # In environments without inspect, we skip this check

    if errors:
        from zope.interface import Invalid
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid('\n'.join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"Candidate does not claim to provide interface {iface}")

    errors = []

    # Check for required methods and their signatures
    for name in iface.names():
        if iface.getAttribute(name).isRequired():
            if not hasattr(candidate, name):
                errors.append(f"Missing required method or attribute: {name}")
            else:
                method = getattr(candidate, name)
                if not callable(method):
                    errors.append(f"Attribute {name} is not callable")
                else:
                    spec = inspect.getfullargspec(method)
                    iface_method_spec = iface.get(name).getSignatureInfo()
                    if iface_method_spec is not None:
                        iface_params = iface_method_spec.required + iface_method_spec.optional
                        if spec.args[1:] != iface_params:  # Skip 'self'
                            errors.append(f"Incorrect signature for method {name}: expected {iface_params}, got {spec.args[1:]}")

    # Check for required attributes
    for name in iface.names():
        if iface.getAttribute(name).isRequired():
            if not hasattr(candidate, name):
                errors.append(f"Missing required attribute: {name}")

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("\n".join(errors))

    return True

