def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metas = [b.__class__ for b in bases]
    if not metas:
        return type
    meta = metas[0]
    for m in metas[1:]:
        if m is not meta:
            raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of all its bases")
    return meta

