def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    tags = set()
    code_block = False
    modified_text = []
    i = 0
    while i < len(text):
        char = text[i]
        if char == '`' and (i == 0 or text[i-1] != '\\'):
            code_block = not code_block
        if not code_block and char == '#':
            tag_start = i
            i += 1
            while i < len(text) and text[i].isalnum():
                i += 1
            tag = text[tag_start+1:i]
            if tag:
                tags.add(tag)
                if replacer:
                    modified_text.append(replacer(tag))
                else:
                    modified_text.append(text[tag_start:i])
        else:
            modified_text.append(char)
        i += 1
    return tags, ''.join(modified_text)

