    try:
        import json
        return json.loads(document)
    except json.JSONDecodeError:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
        result = {}
        for elem in root.iter():
            if elem.tag not in result:
                result[elem.tag] = []
            result[elem.tag].append(elem.attrib)
        return result

